=== FILE: irq_ctrl_cov_tb.sv ===
// Coverage testbench for irq_ctrl.v (N = 8). It extends the approved idle testbench
// (irq_ctrl_idle_tb.sv): reset, ENABLE/MODE readback, level and rising-edge detection
// on every source, mixed modes, W1C clears, CLAIM acknowledges (in and out of range),
// detection winning over a clear or an acknowledge at the same edge, enable masking,
// the fixed-priority irq_id for every source, ignored upper wdata bits, and a reset
// with live state. Every check compares against a small model in this file.
// Inputs change 1 ns after a rising edge; the DUT samples them at the next one.
`timescale 1ns / 1ps
module irq_ctrl_cov_tb;
    logic        clk = 1'b0;
    logic        rst_n = 1'b0;
    logic [7:0]  src = '0;
    logic        we = 1'b0;
    logic [1:0]  addr = 2'd0;
    logic [31:0] wdata = 32'd0;
    logic [31:0] rdata;
    logic        irq;
    logic [4:0]  irq_id;
    int checks = 0, errors = 0;
    logic [8*64-1:0] nonce;
    logic [7:0]  en_m = 8'h00;   // model of the ENABLE register
    logic [7:0]  p;              // expected PENDING during the acknowledge sweep

    irq_ctrl #(.N(8)) dut (.clk(clk), .rst_n(rst_n), .src(src), .we(we), .addr(addr), .wdata(wdata),
                           .rdata(rdata), .irq(irq), .irq_id(irq_id));
    always #5 clk = ~clk;

    function automatic logic [4:0] lowest(input logic [7:0] v);
        logic [4:0] r;
        r = 5'd0;
        for (int k = 7; k >= 0; k--)
            if (v[k]) r = k[4:0];
        return r;
    endfunction

    task automatic tick();
        @(posedge clk);
        #1;
    endtask

    task automatic write_reg(input logic [1:0] a, input logic [31:0] d);
        we = 1'b1;
        addr = a;
        wdata = d;
        tick();
        we = 1'b0;
        wdata = 32'd0;
    endtask

    task automatic expect_reg(input logic [1:0] a, input logic [31:0] expected);
        addr = a;
        #1;
        checks++;
        if (rdata !== expected) begin
            errors++;
            $display("ERROR at %0t: addr %0d read %h, expected %h", $time, a, rdata, expected);
        end
    endtask

    // Checks PENDING, the CLAIM read, and the irq / irq_id outputs for a pending value p.
    task automatic expect_state(input logic [7:0] pend);
        logic [7:0] act;
        logic       exp_irq;
        logic [4:0] exp_id;
        act = pend & en_m;
        exp_irq = |act;
        exp_id = lowest(act);
        expect_reg(2'd2, {24'd0, pend});
        expect_reg(2'd3, {exp_irq, 26'd0, exp_id});
        checks++;
        if (irq !== exp_irq || irq_id !== exp_id) begin
            errors++;
            $display("ERROR at %0t: irq %b id %0d, expected irq %b id %0d", $time, irq, irq_id, exp_irq, exp_id);
        end
    endtask

    initial begin
        // Reset and reset values.
        repeat (3) @(posedge clk);
        #1;
        rst_n = 1'b1;
        tick();
        expect_reg(2'd0, 32'd0);
        expect_reg(2'd1, 32'd0);
        expect_state(8'h00);

        // ENABLE all, MODE all level.
        write_reg(2'd0, 32'h0000_00FF);
        en_m = 8'hFF;
        expect_reg(2'd0, 32'h0000_00FF);
        write_reg(2'd1, 32'h0000_0000);
        expect_reg(2'd1, 32'h0000_0000);

        // Level detection on every source for one cycle; pending holds after src drops.
        src = 8'hFF;
        tick();
        src = 8'h00;
        expect_state(8'hFF);

        // Acknowledge sweep: priority moves from source 0 to source 7.
        p = 8'hFF;
        for (int k = 0; k < 8; k++) begin
            write_reg(2'd3, k);
            p[k] = 1'b0;
            expect_state(p);
        end

        // Level held high: a W1C at the same edge loses to the detection.
        src = 8'h04;
        tick();
        expect_state(8'h04);
        write_reg(2'd2, 32'h0000_0004);
        expect_state(8'h04);
        src = 8'h00;
        write_reg(2'd2, 32'h0000_0004);
        expect_state(8'h00);

        // Level held high: an acknowledge at the same edge loses to the detection.
        src = 8'h40;
        tick();
        expect_state(8'h40);
        write_reg(2'd3, 32'h0000_0006);
        expect_state(8'h40);
        src = 8'h00;
        write_reg(2'd3, 32'h0000_0006);
        expect_state(8'h00);

        // Rising-edge mode on every source.
        write_reg(2'd1, 32'h0000_00FF);
        expect_reg(2'd1, 32'h0000_00FF);
        src = 8'h10;
        tick();
        expect_state(8'h10);
        write_reg(2'd2, 32'h0000_0010);   // src still high: no new edge, the clear wins
        expect_state(8'h00);
        tick();                           // held level: no detection in edge mode
        expect_state(8'h00);
        src = 8'h00;
        tick();                           // falling edge: no detection
        expect_state(8'h00);
        src = 8'h10;
        tick();
        expect_state(8'h10);
        src = 8'h00;
        write_reg(2'd2, 32'h0000_0010);
        expect_state(8'h00);

        // Edges on every source, then an edge at the same edge as a clear of all.
        src = 8'hFF;
        tick();
        src = 8'h00;
        expect_state(8'hFF);
        tick();
        expect_state(8'hFF);
        src = 8'h01;
        write_reg(2'd2, 32'h0000_00FF);
        expect_state(8'h01);
        src = 8'h00;
        write_reg(2'd2, 32'h0000_0001);
        expect_state(8'h00);

        // Enable masking and acknowledges that hit nothing.
        write_reg(2'd0, 32'h0000_000F);
        en_m = 8'h0F;
        expect_reg(2'd0, 32'h0000_000F);
        src = 8'hF0;
        tick();
        src = 8'h00;
        expect_state(8'hF0);              // pending but disabled: irq low
        write_reg(2'd0, 32'h0000_00FF);
        en_m = 8'hFF;
        expect_state(8'hF0);              // irq high, id 4
        write_reg(2'd3, 32'h0000_001F);   // id 31: out of range, ignored
        expect_state(8'hF0);
        write_reg(2'd3, 32'h0000_0008);   // id 8: out of range, ignored
        expect_state(8'hF0);
        write_reg(2'd3, 32'h0000_0000);   // id 0: not pending, no change
        expect_state(8'hF0);
        write_reg(2'd3, 32'h0000_0005);   // acknowledge source 5
        expect_state(8'hD0);
        write_reg(2'd2, 32'h0000_00D0);
        expect_state(8'h00);

        // Upper wdata bits are ignored on every register.
        write_reg(2'd0, 32'hFFFF_FFFF);
        en_m = 8'hFF;
        expect_reg(2'd0, 32'h0000_00FF);
        write_reg(2'd1, 32'hFFFF_FFFF);
        expect_reg(2'd1, 32'h0000_00FF);
        write_reg(2'd2, 32'hFFFF_FFFF);
        expect_state(8'h00);
        write_reg(2'd3, 32'hFFFF_FFFF);
        expect_state(8'h00);
        write_reg(2'd0, 32'hFFFF_FF00);
        en_m = 8'h00;
        expect_reg(2'd0, 32'h0000_0000);
        write_reg(2'd1, 32'hFFFF_FF00);
        expect_reg(2'd1, 32'h0000_0000);

        // Mixed modes: sources 0-3 edge, 4-7 level.
        write_reg(2'd0, 32'h0000_00FF);
        en_m = 8'hFF;
        write_reg(2'd1, 32'h0000_000F);
        expect_reg(2'd1, 32'h0000_000F);
        src = 8'hFF;
        tick();
        expect_state(8'hFF);
        write_reg(2'd2, 32'h0000_00FF);   // level sources still detect, edge sources clear
        expect_state(8'hF0);
        src = 8'h00;
        write_reg(2'd2, 32'h0000_00F0);
        expect_state(8'h00);

        // Reset with live state.
        src = 8'hFF;
        tick();
        expect_state(8'hFF);
        rst_n = 1'b0;
        tick();
        tick();
        en_m = 8'h00;
        expect_reg(2'd0, 32'h0000_0000);
        expect_reg(2'd1, 32'h0000_0000);
        expect_state(8'h00);
        src = 8'h00;
        rst_n = 1'b1;
        tick();
        expect_state(8'h00);

        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "none";
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, (checks > errors ? checks - errors : 0), errors);
        $finish;
    end
endmodule
=== END FILE ===
